import sys

def clip(l, x, r):
    return (x > l and x > r) or (x < l and x < r)

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    a = [int(x) for x in data[1:1 + n]]
    st = [0] * n
    for i in range(1, n - 1):
        if clip(a[i - 1], a[i], a[i + 1]):
            st[i] = 1
    total = sum(st)
    best = total
    for r in range(n):
        cur = total
        for i in (r - 1, r, r + 1):
            if 0 <= i < n:
                cur -= st[i]
        # after removal, a[r-1] has neighbours a[r-2], a[r+1]; a[r+1] has neighbours a[r-1], a[r+2]
        if r - 2 >= 0 and r - 1 >= 0 and r + 1 < n:
            if clip(a[r - 2], a[r - 1], a[r + 1]):
                cur += 1
        if r - 1 >= 0 and r + 1 < n and r + 2 < n:
            if clip(a[r - 1], a[r + 1], a[r + 2]):
                cur += 1
        if cur < best:
            best = cur
    print(best)

main()

