def gen(rng):
    def fmt(a):
        return str(len(a)) + "\n" + " ".join(map(str, a))
    tests = [
        fmt([3, 1]), fmt([1, 2]), fmt([4, 4]), fmt([1, 2, 3]), fmt([1, 3, 2]), fmt([2, 2, 2, 2]),
        fmt([1, 2, 3, 4, 5, 6]), fmt([1, 3, 1, 3, 1, 3, 1, 3]), fmt([5, 1, 5, 1, 5]),
        fmt([-10 ** 9, 10 ** 9, -10 ** 9, 10 ** 9]),
    ]
    for n in (3, 4, 5, 6, 7, 8, 10, 14, 20, 30):
        for _ in range(3):
            lim = rng.choice([1, 2, 5, 100])
            tests.append(fmt([rng.randint(-lim, lim) for _ in range(n)]))
    N = 100000
    M = 10 ** 9
    tests.append(fmt([rng.randint(-M, M) for _ in range(N)]))
    tests.append(fmt([rng.randint(0, 3) for _ in range(N)]))
    tests.append(fmt([(M if i % 2 == 0 else -M) for i in range(N)]))
    tests.append(fmt([i + 1 for i in range(N)]))
    tests.append(fmt([rng.randint(-M, M) if i % 3 else 7 for i in range(N)]))
    return tests

